declare module "@cesium/gltf" {
import { Color,
defined } from "@cesium/core";
/**
 * Contains traversal functions for processing elements of the glTF hierarchy.
 */
export namespace ForEach {
    /**
     * @param gltf - A javascript object containing a glTF asset.
     * @param handler - Called with each buffer.
     * @returns The first defined value returned by the handler.
     */
    function buffer(gltf: any, handler: ForEachElementHandler): any;
}

/**
 * A function called with each glTF object. A defined return value stops the iteration.
 * @param element - The glTF object.
 * @param index - The element's index, or its id in glTF 1.0.
 */
export type ForEachElementHandler = (element: any, index: number | string) => any;

/**
 * A function called with each value of a keyed collection. A defined return value stops the iteration.
 * @param value - The value.
 * @param name - The key of the value.
 */
export type ForEachNamedHandler = (value: any, name: string) => any;

/**
 * A function called with an id. A defined return value stops the iteration.
 * @param id - The id.
 */
export type ForEachIdHandler = (id: number) => any;

/**
 * Adds default glTF values if they don't exist.
 * @param gltf - A javascript object containing a glTF asset.
 * @returns The modified glTF.
 */
export function addDefaults(gltf: any): any;

/**
 * Adds extras._pipeline to each object that can have extras in the glTF asset.
 * This stage runs before updateVersion and handles both glTF 1.0 and glTF 2.0 assets.
 * @param gltf - A javascript object containing a glTF asset.
 * @returns The glTF asset with the added pipeline extras.
 */
export function addPipelineExtras(gltf: any): any;

/**
 * Converts the <code>boundingVolume</code> of a glTF node using the <code>3DTILES_tileset</code>
 * extension to the box or sphere bounding volume format of a 3D Tiles tileset JSON.
 * Only box and sphere shapes are supported.
 * @param boundingVolumeJson - The glTF bounding volume, with a <code>shape</code> index and an optional <code>translation</code>, <code>rotation</code>, and <code>scale</code>.
 * @param shapes - The <code>shapes</code> array of the glTF.
 * @returns The bounding volume in tileset JSON format, with either the box center followed by its half axes, or the sphere center followed by its radius.
 */
export function constructBoundingVolumeJson(boundingVolumeJson: any, shapes: object[]): any | any;

/**
 * Returns the byte stride of the provided accessor.
 * If the byteStride is 0, it is calculated based on type and componentType
 * @param gltf - A javascript object containing a glTF asset.
 * @param accessor - The accessor.
 * @returns The byte stride of the accessor.
 */
export function getAccessorByteStride(gltf: any, accessor: any): number;

/**
 * Returns a function to read and convert data from a DataView into an array.
 * @param componentType - Type to convert the data to.
 * @returns Function that reads and converts data.
 */
export function getComponentReader(componentType: number): ComponentReader;

/**
 * A function that reads consecutive components from a DataView into an array.
 * @param dataView - The data view to read from.
 * @param byteOffset - The byte offset applied when reading from the data view.
 * @param numberOfComponents - The number of components to read.
 * @param result - An array storing the components that are read.
 */
export type ComponentReader = (dataView: DataView, byteOffset: number, numberOfComponents: number, result: number[]) => void;

/**
 * Gets the local transform of a glTF node as a column-major array of 16 numbers.
 * @param nodeJson - The glTF node.
 * @returns The transform, or <code>undefined</code> if the node has no <code>matrix</code>, <code>translation</code>, <code>rotation</code>, or <code>scale</code>.
 */
export function getNodeTransform(nodeJson: any): number[] | undefined;

/**
 * Utility function for retrieving the number of components in a given type.
 * @param type - glTF type
 * @returns The number of components in that type.
 */
export function numberOfComponentsForType(type: string): number;

/**
 * Convert a binary glTF to glTF.
 *
 * The returned glTF has pipeline extras included. The embedded binary data is stored in gltf.buffers[0].extras._pipeline.source.
 * @param glb - The glb data to parse.
 * @returns A javascript object containing a glTF asset with pipeline extras included.
 */
export function parseGlb(glb: Uint8Array): any;

/**
 * Iterate through the objects within the glTF and delete their pipeline extras object.
 * @param gltf - A javascript object containing a glTF asset.
 * @returns glTF with no pipeline extras.
 */
export function removePipelineExtras(gltf: any): any;

/**
 * Update the glTF version to the latest version (2.0), or targetVersion if specified.
 * Applies changes made to the glTF spec between revisions so that the core library
 * only has to handle the latest version.
 * @param gltf - A javascript object containing a glTF asset.
 * @param [options] - Options for updating the glTF.
 * @param [options.targetVersion] - The glTF will be upgraded until it hits the specified version.
 * @param [options.baseColorTextureNames] - Names of uniforms that indicate base color textures.
 * @param [options.baseColorFactorNames] - Names of uniforms that indicate base color factors.
 * @returns The updated glTF asset.
 */
export function updateVersion(gltf: any, options?: {
    targetVersion?: string;
    baseColorTextureNames?: string[];
    baseColorFactorNames?: string[];
}): any;

/**
 * Checks whether the glTF uses the given extension.
 * @param gltf - A javascript object containing a glTF asset.
 * @param extension - The name of the extension.
 * @returns Whether the glTF uses the given extension.
 */
export function usesExtension(gltf: any, extension: string): boolean;


}
